public class ContactsListWithController {
    private String sortOrder = 'LastName';

    public List<Contact> getContacts() {          // {! contacts } 가 이 getter 호출
        return Database.query(
            'SELECT Id, FirstName, LastName, Title, Email FROM Contact ' +
            'ORDER BY ' + sortOrder + ' ASC LIMIT 10');
    }
    public void sortByLastName()  { this.sortOrder = 'LastName'; }   // 액션 메서드
    public void sortByFirstName() { this.sortOrder = 'FirstName'; }
}
